const mail = $('Email Trigger (IMAP)').first().json || {};
const token = String($('BFF Login').first().json.access_token || '').trim();
if (!token) throw new Error('BFF login did not return access_token');
const bff = String($env.BFF_URL || '').replace(/\/$/, '');
if (!bff) throw new Error('BFF_URL is required');

const headers = mail.headers && typeof mail.headers === 'object' ? mail.headers : {};
const meta = mail.metadata && typeof mail.metadata === 'object' ? mail.metadata : {};

function pickHeader(...keys) {
  for (const key of keys) {
    const v = headers[key] ?? headers[key.toLowerCase()] ?? headers[key.toUpperCase()];
    if (v == null) continue;
    if (Array.isArray(v)) return v.map(String).join(', ');
    return String(v);
  }
  return '';
}

function extractEmails(raw) {
  const text = String(raw || '');
  const out = [];
  const re = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;
  let m;
  while ((m = re.exec(text))) {
    const addr = m[0].toLowerCase();
    if (!out.includes(addr)) out.push(addr);
  }
  return out;
}

const toRaw = mail.to || pickHeader('to', 'delivered-to', 'envelope-to', 'x-original-to');
const ccRaw = mail.cc || pickHeader('cc');
const fromRaw = mail.from || pickHeader('from');
const subject = String(mail.subject || pickHeader('subject') || '').trim();
const body = String(mail.text || mail.textPlain || mail.html || mail.textAsHtml || '').trim();
let messageId = String(
  meta.messageId || mail.messageId || pickHeader('message-id', 'messageid') || '',
).trim();
messageId = messageId.replace(/^<|>$/g, '').trim();
if (!messageId) {
  const seed = [fromRaw, toRaw, subject, mail.date || meta.date || ''].join('|');
  messageId = `ce-imap-${Buffer.from(seed).toString('base64url').slice(0, 48)}`;
}

const toCandidates = [...extractEmails(toRaw), ...extractEmails(ccRaw)];
const fromEmail = extractEmails(fromRaw)[0] || '';

let routeMap = {};
try {
  const rawMap = String($env.CRM_INBOUND_ROUTE_MAP || '').trim();
  if (rawMap) routeMap = JSON.parse(rawMap);
} catch (e) {
  throw new Error('CRM_INBOUND_ROUTE_MAP must be valid JSON object');
}

let ownerId = '';
let routeSource = '';
for (const addr of toCandidates) {
  const hit = routeMap[addr] || routeMap[addr.toLowerCase()];
  if (hit != null && String(hit).trim()) {
    ownerId = String(hit).trim();
    routeSource = `route_map:${addr}`;
    break;
  }
}

if (!ownerId) {
  for (const addr of toCandidates) {
    try {
      const row = await this.helpers.httpRequest({
        method: 'GET',
        url: `${bff}/api/v1/users/email:${encodeURIComponent(addr)}`,
        headers: {
          Authorization: `Bearer ${token}`,
          'X-CRM-Automation': 'n8n',
        },
        json: true,
      });
      const id = row && row.id != null ? String(row.id).trim() : '';
      if (id) {
        ownerId = id;
        routeSource = `users.email:${addr}`;
        break;
      }
    } catch (e) {
      // 404 / no match — try next recipient
    }
  }
}

if (!ownerId) {
  ownerId = String($env.CRM_INBOUND_FALLBACK_OWNER_ID || '').trim();
  if (ownerId) routeSource = 'fallback';
}

const name = subject || `Email ${messageId.slice(0, 12)}`;
return [{
  json: {
    hasOwner: Boolean(ownerId),
    ownerId,
    routeSource,
    toCandidates,
    token,
    inboxPayload: {
      name,
      subject: subject || null,
      body,
      type: 'email',
      status: 'new',
      from_email: fromEmail || null,
      external_message_id: messageId,
      owner_id: ownerId || null,
    },
  },
}];

const ctx = $input.first().json;
throw new Error(
  'Inbound email: no owner matched for recipients ' +
    JSON.stringify(ctx.toCandidates || []) +
    '. Set CRM_INBOUND_FALLBACK_OWNER_ID or CRM_INBOUND_ROUTE_MAP, or ensure To matches an active app user email.',
);
